+static void radix_sort_u32(uint32_t* a, size_t n) {
+    if (n < 2) return;
+    std::vector<uint32_t> tmp(n);
+    uint32_t* src = a;
+    uint32_t* dst = tmp.data();
+    constexpr int passes = 4;
+    for (int pass = 0; pass < passes; ++pass) {
+        uint32_t count[256] = {0};
+        for (size_t i = 0; i < n; ++i) {
+            uint8_t byte = (src[i] >> (pass * 8)) & 0xFF;
+            ++count[byte];
+        }
+        uint32_t sum = 0;
+        for (int i = 0; i < 256; ++i) {
+            uint32_t c = count[i];
+            count[i] = sum;
+            sum += c;
+        }
+        for (size_t i = 0; i < n; ++i) {
+            uint8_t byte = (src[i] >> (pass * 8)) & 0xFF;
+            dst[count[byte]++] = src[i];
+        }
+        std::swap(src, dst);
+    }
+    if (src != a) {
+        std::memcpy(a, src, n * sizeof(uint32_t));
+    }
